def next_action(result):
    if result.get("status") == "running":
        process_id = result.get("process_id")
        return {"tool":"get_process_status", "process_id":process_id}
    elif result.get("status") == "completed" and result.get("exit_code") == 0:
        return {"tool":"final_report", "success":True}
    elif result.get("status") == "completed" and result.get("exit_code") != 0:
        return {"tool":"final_report", "success":False}
    else:
        raise ValueError("Unknown status")
